      "後日、同患者が再び来局し、不安やイライラが強いことから漢方薬を紹介してほしいと依頼された。この患者に加味逍遙散（注）を紹介したが、この漢方薬を長期服用する場合、留意すべき副作用として腸間膜静脈硬化症が報告されている。\n（注）サイコ、シャクヤク、トウキ、ソウジュツ、ブクリョウ、サンシシ、ボタンピ、カンゾウ、ショウキョウ、ハッカから構成される処方\nこの副作用の原因と考えられる生薬として正しいのはどれか。1つ選べ。なお、写真左下のスケールバーは1 cmである。",

