    caseContext:
      "89歳女性。体重40 kg。高血圧症及び慢性心不全に対して処方1で薬物治療を行っている。独居で入院拒否があるため、医師と薬剤師、看護師が訪問している。最近、下腿浮腫が出現し、労作時の息苦しさや疲労感が強くなってきたため、血液検査を実施したところ、脳性ナトリウム利尿ペプチド前駆体N端フラグメント（NT-proBNP）値が3ヶ月前の450 pg/mLから下記の検査値になっていた。\n\n（処方1）\nエナラプリルマレイン酸塩錠5 mg　1回1錠（1日1錠）\nビソプロロールフマル酸塩錠0.625 mg　1回1錠（1日1錠）\nアゾセミド錠60 mg　1回1錠（1日1錠）\nスピロノラクトン錠50 mg　1回1錠（1日1錠）\n1日1回　朝食後　14日分\n\n（検査値）\nNa 141 mEq/L、K 4.8 mEq/L、eGFR 54 mL/min/1.73 m2、NT-proBNP 1,180 pg/mL\n※なお、NT-proBNP値900 pg/mL以上は治療対象となる心不全の可能性が高い。\n\nその後、訪問医は継続中だった処方1のうち、エナラプリルのみを中止して、新たに処方2を追加した。\n\n（処方2）\nサクビトリルバルサルタンNa水和物錠50 mg　1回1錠（1日2錠）\n1日2回　朝夕食後　7日分",
