      "65歳女性。高血圧症、骨粗しょう症、慢性便秘症及び脂質異常症の治療でかかりつけ薬局を利用し、処方1及び処方2の薬剤を2年間服用している。さらに、脂質異常症については食事療法の効果が不十分で、処方3を2ヶ月前に開始した。\n\n（処方1）\nアムロジピン錠5 mg　1回1錠（1日1錠）\nエルデカルシトールカプセル0.75 μg　1回1カプセル（1日1カプセル）\n1日1回　朝食後　14日分\n\n（処方2）\n酸化マグネシウム錠330 mg　1回1錠（1日2錠）\nオメガ-3脂肪酸エチル粒状カプセル2 g　1回1包（1日2包）\n1日2回　朝夕食後　14日分\n\n（処方3）\nフェノフィブラート錠53.3 mg　1回1錠（1日1錠）\n1日1回　朝食後　14日分\n\n処方3開始直前の空腹時検査値：\nLDL-C 126 mg/dL、HDL-C 58 mg/dL、TG（トリグリセリド）198 mg/dL\n\n昨夜から全身の筋肉痛が生じているため、一般用医薬品の痛み止めを求めて来局した。昨日は、日課としている約2 kmの散歩しかしておらず、普段はその程度の運動で筋肉痛は起こらないと言う。また、胃が弱いので内服ではなく、テレビコマーシャルで見たロキソプロフェン含有テープ剤の購入を希望している。",
