      "筋肉の障害や壊死があると、筋細胞内の酵素が血中に漏れ出すため、クレアチンキナーゼ（CK）や乳酸デヒドロゲナーゼ（LDH）が上昇しやすくなります。特にCKは骨格筋や心筋に多く、筋肉の状態をみる代表的な指標です。LDHも筋肉を含む多くの組織に存在し、組織障害の指標として参考になります。ビリルビンは主に肝胆道系や溶血、ヘモグロビンは貧血など、尿酸はプリン体代謝や痛風・腎機能に関連する指標であり、筋肉の状態を直接みる目的では優先度は高くありません。"
