      "3歳5ヶ月女児。台所で沸かしていたやかんのお湯をかぶり、体表の熱傷（Ⅱ度）で救急搬送された。入院14日目に39℃の発熱を認め、熱傷創部からセフェム系抗菌薬に感受性のある［A］が同定されたため、セフタジジムを2週間投与し、症状が改善したため終了した。\n抗菌薬終了7日後に、再び38℃の発熱及び熱傷創部に膿を認めた。膿を検査したところ、［A］が同定された。検出された［A］の薬剤感受性試験及び患者の血液検査の結果は、以下のとおりである。\n\n（薬剤感受性試験の結果）\n抗菌薬：ピペラシリン、MIC（μg/mL）：≤2、判定：Susceptible（感性）\n抗菌薬：タゾバクタム・ピペラシリン、MIC（μg/mL）：≤2、判定：Susceptible（感性）\n抗菌薬：セフタジジム、MIC（μg/mL）：>16、判定：Resistant（耐性）\n抗菌薬：メロペネム、MIC（μg/mL）：≤0.25、判定：Susceptible（感性）\n抗菌薬：シプロフロキサシン、MIC（μg/mL）：≤0.25、判定：Susceptible（感性）\n抗菌薬：アミカシン、MIC（μg/mL）：2、判定：Susceptible（感性）\n\n（検査値）\n血清アルブミン 4.2 g/dL、CRP 8.0 mg/dL、白血球 17,600/μL、AST 24 IU/L、ALT 11 IU/L、血清クレアチニン 0.24 mg/dL、BUN 10 mg/dL\n\nなお、この患者はアモキシシリン水和物に対するアレルギー歴がある。",
    field: "生物",

    question:
      "A に該当する細菌に関しては、培養検査等により以下の情報が得られている。A はどれか。1つ選べ。\n「好気条件で増殖する。グラム陰性菌である。鞭毛を有する。芽胞は形成しない。色素ピオシアニンを産生する。バイオフィルムを形成する。」",

