    caseContext:
      "55歳男性。身長165cm、体重46kg。脳血管障害により3年前から寝たきりの状態となり自宅療養中であった。ベッドから誤って転落し、大腿骨を骨折したため、入院となった。入院時、仙骨部に褥瘡が認められ、病態としては黄色期と判断されたことから、褥瘡チームが介入した。褥瘡チームが回診で確認したところ滲出液、創周囲の感染徴候が認められた。",
