    field: "実務",

    question:
      "猛暑日が続き、連日にわたって熱中症警戒アラートが発表されているため、多くの人がドラッグストアに病者用食品の経口補水液を購入に来た。購入希望者から薬剤師に、脱水や熱中症への対策について相談が度々あった。\n\n薬剤師が、購入希望者に対して行う、脱水や熱中症に関する説明内容として適切なのはどれか。2つ選べ。",

