    caseContext:
      "70歳男性。同居している息子夫婦に付き添われて来局。20歳の頃より喫煙習慣があり（ブリンクマン指数：1,200）、現在も1日に10本程度喫煙している。また職業上の粉じん曝露歴があった。数年前より労作時の息切れが出現し、徐々に症状が悪化したために近医を受診し、慢性閉塞性肺疾患（COPD）と診断され、以下の処方が出された。\n\n（処方）\nチオトロピウム臭化物吸入用カプセル 18 μg　1回1カプセル\n1日1吸入　全56カプセル",
    field: "実務",

    question:
      "70歳男性。同居している息子夫婦に付き添われて来局。20歳の頃より喫煙習慣があり（ブリンクマン指数：1,200）、現在も1日に10本程度喫煙している。また職業上の粉じん曝露歴があった。数年前より労作時の息切れが出現し、徐々に症状が悪化したために近医を受診し、慢性閉塞性肺疾患（COPD）と診断され、以下の処方が出された。\n\n（処方）\nチオトロピウム臭化物吸入用カプセル18 μg 1回1カプセル\n1日1吸入 全56カプセル\n\n処方薬の注意すべき主な副作用はどれか。2つ選べ。",

    choices: [
    "排尿障害",
    "徐脈",
    "口腔内カンジダ症",
    "下痢",
    "口渇"
    ],

    answer: [0, 4],


    explanation:
      "チオトロピウムは長時間作用性抗コリン薬（LAMA）で、COPDの気管支拡張に用いられます。抗コリン作用により唾液分泌が低下して口渇が起こりやすく、また膀胱排尿筋の収縮が抑えられるため、排尿障害（特に前立腺肥大症がある高齢男性など）に注意します。徐脈は主な副作用ではなく、むしろ抗コリン作用では頻脈に注意することがあります。口腔内カンジダ症は吸入ステロイド薬で問題になりやすい副作用です。下痢もチオトロピウムの主な副作用としては考えにくく、抗コリン作用では便秘に注意します。"
