    caseContext:
      "43歳男性。既婚で妻と二人暮らし。糖尿病治療のため、インスリンの自己注射を行っている。インスリン療法開始から1年程度経過し、血糖値は正常値に近づいてきた。しかし、食事をとらずに注射したときや入浴中の低血糖症状による意識障害により、救急搬送を何度か経験しており、グルカゴン注射液を家族が投与できるよう3ヶ月前に処方（処方1）された。しかし、その後重症低血糖による意識障害を起こしている本人を前にして、妻が注射液の調製を失敗してしまい、救急車を待つことしかできなかった。そこで、今後の低血糖対策として、グルカゴン点鼻粉末剤（処方2）を使用できるよう、妻同席のもと医師による説明が実施され、薬剤師には薬剤の使用方法等について説明の依頼があった。\n\n（処方1）\nグルカゴン（遺伝子組換え）注射用 1 mg　1回1本\n（溶解用注射用水 1 mL 添付してください）\n低血糖時　注射用水で溶解後に筋注　1回分\n\n（処方2）\nグルカゴン点鼻粉末剤 3 mg　1回1個\n低血糖時　鼻腔内に噴霧　1回分",
