    "処方2で投与する場合に処方1の場合と同等の血中グルコース濃度上昇作用を得るためには、同用量のグルカゴンが必要である。",
    "処方2で投与した場合、投与後30分までの血中グルコース濃度は約70mg/dLであり、最大血中グルコース濃度は140mg/dLを超える値まで上昇する。"
