      "73歳男性。体重60 kg。慢性気管支炎のため、長期治療（エンクラッセ62.5 μg エリプタ30吸入用（注）、1日1回1吸入）を実施中である。咳嗽症状が悪化し、39℃以上の発熱、茶色の喀痰症状があり、肺炎疑いのため、入院加療となった。\n最近では肺炎を繰り返しており、精査を行ったところ、末梢血好酸球増加、アスペルギルスの抗体検査及び喀痰検査陽性、レントゲン画像所見などから、アレルギー性気管支肺アスペルギルス症と診断され、ボリコナゾール200 mg静注用を投与することとなった。投与量は、ボリコナゾールとして初日は1回6 mg/kgを1日2回、2日目以降は1回3 mg/kgを1日2回とした。投与開始から4日目と8日目に血中濃度を測定した。測定結果がわかるまでに数日を要することから、病棟カンファレンスにおいて、薬物治療に関する確認事項を共有した。\n（注）1吸入でウメクリジニウムとして62.5 μgを吸入できるドライパウダー吸入剤",
