      "53歳男性。以前から、A病院内科で高血圧症、脂質異常症、糖尿病、胃潰瘍、腰痛症に対して治療を受けており、症状は安定していた。最近、仕事のストレスのためか気分が落ち込むことが多く、食欲不振、不眠などが続くため、B心療内科を受診した。うつ病と診断され、処方箋を持って、かかりつけの薬局を訪れた。\n\n（処方）\nフルボキサミンマレイン酸塩錠25 mg　1回1錠（1日2錠）\n1日2回　朝夕食後　14日分\n\n（薬歴に記載されていたA病院内科での処方内容）\nニフェジピン徐放錠20 mg　1回1錠（1日1錠）\n1日1回　朝食後　14日分\nシンバスタチン錠5 mg　1回1錠（1日1錠）\n1日1回　夕食後　14日分\nメトホルミン塩酸塩錠500 mg　1回1錠（1日2錠）\nファモチジン口腔内崩壊錠20 mg　1回1錠（1日2錠）\n1日2回　朝夕食後　14日分\nチザニジン錠1 mg　1回1錠（1日3錠）\n1日3回　朝昼夕食後　14日分",
    field: "実務",

    question:
      "かかりつけ薬剤師が処方監査した際、心療内科と内科の処方薬剤の中に併用禁忌の組合せがあるため、疑義照会を行うこととなった。その疑義照会の原因となる薬剤はどれか。1つ選べ。",

