    "2回目投与直前のバンコマイシン血中濃度（μg/mL）：8、定常状態におけるトラフ値（μg/mL）：16",
    "2回目投与直前のバンコマイシン血中濃度（μg/mL）：8、定常状態におけるトラフ値（μg/mL）：20",
    "2回目投与直前のバンコマイシン血中濃度（μg/mL）：12、定常状態におけるトラフ値（μg/mL）：20",
    "2回目投与直前のバンコマイシン血中濃度（μg/mL）：12、定常状態におけるトラフ値（μg/mL）：40"
