      "6歳男児。てんかん小発作の治療のため、以前からバルプロ酸Naシロップ5％を服用している。進学に伴い、薬局薬剤師に服用回数を減らすことができないかとの相談があった。この男児は、2ヶ月前に上気道炎にて受診時に、錠剤が処方されたが服用できなかったため、散剤に変更となったと薬歴に記載されていた。そこで、セレニカR顆粒40％（注）の処方への変更を主治医に提案することになった。\n\n（注）セレニカR顆粒40％：1 g中バルプロ酸ナトリウムを400 mg含有する徐放性顆粒\n\n（処方）\nバルプロ酸Naシロップ5％　1回4 mL（1日12 mL）\n1日3回　朝昼夕食後　30日分",
