    field: "実務",

    question:
      "男性は、次第に歩行が拙劣になり、夜間にトイレでつまづいて転倒し、腰椎圧迫骨折と診断された。痛みのため歩行や長時間の起き上がりは困難でありベッド上の生活となった。ヘルパーの介助を受け服薬しているが、ヘルパーのいない起床時の薬は自分ではほぼ服用できていない。\n\nこの状況を踏まえ、在宅医療サービス担当者会議が開催された。\n\nこの患者に追加する治療薬として適切なのはどれか。2つ選べ。",

