      "42歳女性。半年前に両側手指関節及び両側膝関節の痛みを自覚し病院を受診した。検査の結果、関節リウマチと診断され、処方1による治療を受けていた。症状のコントロールが不十分だったためメトトレキサートが漸増されたが、多発性関節炎は持続した。最近では仕事にも支障をきたすようになったため、治療方針が変更されることになった。この患者は小児期に水痘に罹患した既往がある。\n\n検査値：CRP 5.0 mg/dL、リウマトイド因子陽性、抗CCP抗体（抗環状シトルリン化ペプチド抗体）陽性、抗核抗体陰性、AST 25 IU/L、ALT 15 IU/L、eGFR 80 mL/min/1.73 m2\n\n処方1：\nメトトレキサートカプセル 2 mg　1回1カプセル（1日2カプセル）　毎週 日曜日1日2回　9時、21時　4日分（投与実日数）\nメトトレキサートカプセル 2 mg　1回1カプセル（1日1カプセル）　毎週 月曜日1日1回　9時　4日分（投与実日数）",
    field: "実務",

    question:
      "治療方針が変更されて2週間後、患者が来院し、診察前の薬剤師との面談で「左腰部から背部に沿ってかゆみがあって、昨日から痛み出した」と訴えた。薬剤師は、患者情報を収集して副作用を疑い、医師へ情報提供を行った。医師は診察後バラシクロビルを処方した。\n\n薬剤師が副作用を疑うきっかけになった患者情報はどれか。2つ選べ。",

    choices: [
    "メトトレキサートの服用状況",
    "追加した治療薬の処方内容",
    "年齢と性別",
    "水痘ワクチンの接種歴",
    "肝機能、腎機能"
    ],

    answer: [0, 1],


    explanation:
      "左腰部から背部に沿ったかゆみ・痛みは、帯状疱疹を疑う訴えであり、バラシクロビルが処方されていることからもその対応と考えられます。メトトレキサートは免疫抑制作用があり、服用状況によって感染症リスクが高まるため、副作用・有害事象を疑うきっかけになります。また、追加された治療薬が免疫を抑える薬剤（生物学的製剤やJAK阻害薬など）であれば、帯状疱疹の発現リスクに注意が必要です。年齢は帯状疱疹のリスク因子ですが、性別と合わせて副作用を疑う直接的な情報とはいえません。水痘ワクチン接種歴は予防面では重要ですが、今回の副作用疑いの主な根拠ではありません。肝機能・腎機能は薬剤選択や用量調節には関係しますが、帯状疱疹発症を疑う直接のきっかけとしては優先度が低いです。"
