    caseContext:
      "67歳女性。身長155 cm、体重43 kg。2年前より心窩部痛を自覚し、外来を受診。CT検査などで膵臓がん、肝転移（Stage IV）と診断された。一次治療として、フルオロウラシル＋イリノテカン塩酸塩＋オキサリプラチン＋レボホリナート（FOLFIRINOX）療法を導入した。1クール目Day 8に発熱があり再来院した。処方1を服用中であり、全身倦怠感が強く入院加療となった。担当医から追加処方（処方2）の連絡を受けて、カンファレンスで今後の方針について協議することになった。\n\n再来院時の患者背景：パフォーマンスステータス（PS）1、腋窩温38.5 ℃、血圧120/80 mmHg。\n\n処方1：酸化マグネシウム錠250 mg　1回1錠（1日3錠）、1日3回　朝昼夕食後　14日分。\n\n処方2：レボフロキサシン錠500 mg　1回1錠（1日1錠）、1日1回　朝食後　7日分。アセトアミノフェン錠200 mg　1回2錠、発熱時　10回分（20錠）。\n\n検査値：白血球（/μL）Day 1 7,800、Day 8 1,400。好中球（/μL）Day 1 5,800、Day 8 300。赤血球（×10^4/μL）Day 1 400、Day 8 380。ヘモグロビン（g/dL）Day 1 12.3、Day 8 11.9。血小板（×10^4/μL）Day 1 22、Day 8 20。AST/ALT（IU/L）Day 1 20/21、Day 8 30/29。eGFR（mL/min/1.73 m²）Day 1 89、Day 8 70。",
