      "64歳女性。身長155 cm、体重51 kg。うつ病の既往歴あり。胃がん腹膜播種転移（Stage IV、HER2陰性）に対しテガフール・ギメラシル・オテラシル（80 mg/m2）＋シスプラチン（60 mg/m2）併用療法を開始したが、3ヶ月後に腫瘍の増悪を認めた。二次治療としてパクリタキセル（80 mg/m2）＋ラムシルマブ（8 mg/kg）併用療法を施行した。徐々に末梢神経障害が認められ、処方1及び2の処方薬を服用していた。末梢神経障害は落ち着いたが、がん疼痛NRS（注）8を認めたため、トラマドール口腔内崩壊錠は処方3に変更され、服用開始3日目に患者面談を行った。（注）NRS：Numerical Rating Scale。\n\n（処方1）\nトラマドール塩酸塩口腔内崩壊錠50 mg　1回2錠（1日6錠）\nメトクロプラミド錠5 mg　1回2錠（1日6錠）\n酸化マグネシウム細粒83％　1回500 mg（1日1,500 mg）\n1日3回　朝昼夕食後　7日分\n\n（処方2）\nアミトリプチリン塩酸塩錠25 mg　1回2錠（1日2錠）\nゾルピデム酒石酸塩錠5 mg　1回1錠（1日1錠）\n1日1回　就寝前　7日分\n\n（処方3）\nオキシコドン徐放錠10 mg　1回1錠（1日2錠）\n1日2回　朝夕食後　7日分\n\n（検査値）\nAST（IU/L）：面談7日前 11、面談時 9\nALT（IU/L）：面談7日前 20、面談時 14\nBUN（mg/dL）：面談7日前 25.4、面談時 30.9\nCCr（mL/min）：面談7日前 45.1、面談時 35.5\nNa（mEq/L）：面談7日前 138、面談時 135\nK（mEq/L）：面談7日前 3.8、面談時 4.5\nCl（mEq/L）：面談7日前 99、面談時 101\n空腹時血糖（mg/dL）：面談7日前 111、面談時 108\n\n面談内容は以下のとおり。\n患者：麻薬と聞いて不安だったけど、痛み止めが効いたよ。\n薬剤師：痛みが落ち着いてよかったですね。食事とお通じはいかがですか。\n患者：ご飯は食べてます。お通じは、トイレの時にいきみますが、スッキリしなくて残った感じがあります。",
    field: "病態",

    question:
      "この患者の病態と治療に関する記述として、正しいのはどれか。2つ選べ。",

