    answer: [0, 3],


    explanation:
      "本問は、進行・再発胃がんなどで用いられるラムシルマブを含む治療を想定した内容です。胃がんでは腫瘍マーカーとしてCEAやCA19-9が上昇することがあり、治療効果判定や経過観察の参考になります。ラムシルマブはVEGFR-2阻害薬で、出血、高血圧、蛋白尿、血栓塞栓症などに注意が必要です。重度の動脈血栓塞栓症が出現した場合は中止を考慮します。Gleasonスコアは前立腺がんの悪性度評価に用いられるため、本病態の予後評価ではありません。二次治療で特に注意する代表的な副作用はラムシルマブ関連の血管系有害事象や、併用薬による骨髄抑制・末梢神経障害などで、横紋筋融解症が中心ではありません。トラスツズマブはHER2陽性胃がんで主に一次治療から併用を考慮する薬剤であり、二次治療抵抗性時に一律に追加するものではありません。"
