    caseContext:
      "厚生康太（こうせい　こうた）氏、75歳男性。身長170 cm、体重65 kg。一過性脳虚血発作で入院し、再発予防目的でプラビックス錠（注）25 mgが1回2錠、1日1回の処方で服薬開始となった。2023年7月1日に起床時のふらつきと意識障害をきたし、近医へ救急搬送され、緊急入院となった。入院時の血糖値33 mg/dL、入院翌日の空腹時血糖値14 mg/dL、血中インスリン濃度127.5 μIU/mL（基準値2.7～10.4）であった。プラビックス錠は入院直後に中止された。検査の結果、患者はプラビックス錠の副作用であるインスリン自己免疫症候群と診断された。入院7日後には検査所見、自覚症状ともに改善した。薬剤師は医薬品・医療機器等安全性情報報告制度に基づき、医薬品安全性情報報告書を作成するとともに、実務実習中の薬学部学生にも報告書の作成の練習をしてもらうこととした。（注）プラビックス錠：クロピドグレル硫酸塩錠",
