    caseContext:
      "13歳男性。身長135 cm、体重40 kg。近隣の公立病院脳神経外科にて頭蓋咽頭腫の摘出術を受けたものの、血中下垂体ホルモン濃度の異常は改善せず、汎下垂体機能低下症と診断され、いくつかのホルモン補充療法の一つとして成長ホルモン補充療法を行うこととなった。処方医より「ソマトロピン（遺伝子組換え）製剤を使用したいが、患児及び患児の両親が先行バイオ医薬品とバイオ後続品（バイオシミラー）のどちらを選択するかを判断できるように説明してほしい。」との依頼を受け、病院薬剤師から先行バイオ医薬品とバイオ後続品の相違について説明を行うこととなった。",
