    "アンブロキソール塩酸塩は、咳の原因となる喉にからまるしつこい痰を出しやすくします。",
    "L-カルボシステインは、咳中枢に働き、咳を鎮めます。",
    "ジヒドロコデインリン酸塩は、くしゃみ、鼻水、鼻づまりの症状を抑えます。",
